"""Model artifact record database model."""

from __future__ import annotations

import uuid
from typing import Any

from sqlalchemy import (
    JSON,
    BigInteger,
    ForeignKey,
    String,
    Uuid,
)
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.models.base import Base, TimestampMixin, UUIDMixin


class ModelArtifactRecord(Base, UUIDMixin, TimestampMixin):
    """Physical or serialized artifact generated by a training job or external upload."""

    __tablename__ = "model_artifacts"

    model_definition_id: Mapped[uuid.UUID | None] = mapped_column(
        Uuid(as_uuid=True),
        ForeignKey("model_definitions.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )
    training_job_id: Mapped[uuid.UUID | None] = mapped_column(
        Uuid(as_uuid=True),
        ForeignKey("training_jobs.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )
    artifact_path: Mapped[str] = mapped_column(String(500), nullable=False)
    checksum: Mapped[str] = mapped_column(String(128), nullable=False)
    file_size_bytes: Mapped[int] = mapped_column(BigInteger, default=0, nullable=False)
    framework: Mapped[str] = mapped_column(String(50), default="pytorch", nullable=False)
    artifact_metadata: Mapped[dict[str, Any]] = mapped_column(
        JSON,
        default=dict,
        nullable=False,
    )

    model_definition = relationship("ModelDefinition", back_populates="artifacts")
    training_job = relationship("TrainingJob", back_populates="artifacts")
